import logo from "src/assets/svg/logo.png";
import { useAutomotiveSoundStore, } from "src/store/store";
import { getMode } from "src/utils/helpers"
import QuantityInput from "./quantity-input/Quantity.input";

const Header = () => {
    const { json_data, sounds, activeSound, seats } = useAutomotiveSoundStore();

    function resolveSubtitle() {
        return getMode(sounds, activeSound)?.subtitle || json_data.subtitle
    }

    return (
        <div className="c-heading">
            <div className={"c-heading__bg " + (json_data.style?.images?.car_header != undefined ? json_data.style.images.car_header : 'dark')}>
                <img src={json_data.images.car_header} alt="" />
            </div>
            <div className="c-heading__top">
                <div className="c-heading__top-brand">
                    <img src={logo} alt="Logo" />
                </div>
                <div className="c-heading__top-title">{json_data.title}</div>
            </div>
            <div className="c-heading__bottom">
                <div className="brand-logo">
                    <img src={json_data.images.car_brand} alt="Car brand" />
                </div>
                <div className="car-brand">
                    <div className="car-brand__title">{json_data.car_model}</div>
                    <div className="car-brand__channels">{resolveSubtitle()}</div>
                </div>
                <div className="master-gain">
                    <div className="master-gain__title">Master Gain</div>
                    <div className="master-gain__input">
                        <QuantityInput />
                    </div>
                </div>
            </div>
        </div>
    );
};
export default Header;
