import React, { useEffect, useRef, useCallback } from 'react';
import { useAutomotiveSoundStore } from "./store/store";
import Navbar from "./components/Navbar";
import Landing from "./components/Landing";
import Footer from "./components/Footer";
import ApiComponent from "./components/Api";
import Notification from "./components/notification/Notification";

function App() {
    const { json_data, setErrorMessage, captureLogsAndErrors } = useAutomotiveSoundStore();
    const isInitialMount = useRef(true);

    // Function to handle unhandled promise rejections
    const handleUnhandledRejection = useCallback((event:any) => {
        console.error('Uncaught Promise error:', event.reason);
        setErrorMessage(String(event.reason));
    }, [setErrorMessage]);

    const appRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (isInitialMount.current) {
            isInitialMount.current = false;

            // Add the event listener for error message
            window.addEventListener('unhandledrejection', handleUnhandledRejection);

            // Capture the logs and errors in a file
            captureLogsAndErrors();
        }

        // Pass the states from the json to the scss
        if (json_data.style && Object.keys(json_data).length > 0 && Object.entries(json_data.style)) {
            Object.entries(json_data.style).forEach(([category_name]) => {
                Object.entries(json_data.style[category_name]).forEach(([key, value]) => {
                    document.documentElement.style.setProperty(`--${category_name}_${key}`, value as string)
                });
            });
        }
    }, [captureLogsAndErrors, handleUnhandledRejection, json_data]);

    return (
        <div className={"App"}>
            <ApiComponent />
            {Object.keys(json_data).length !== 0 && (<>
                <div ref={appRef}>

                    <Navbar />

                    <Notification />

                    <Landing />

                    <Footer />
                </div>
            </>)}
        </div>
    );
}

export default App;
