
import {TupleType} from 'typescript';

import {Seat, Sound, SoundMode} from '../store/store';
import {ApiGetAllArchives} from '../utils/api';

// Helper function that finds what is the selected seat
export function findSelectedSeat(seats: boolean[], configJson: any): Seat {
  for (const [seatNumberKey, is_selected] of Object.entries(seats)) {
    if (is_selected) {
      return configJson.seats[parseInt(seatNumberKey, 10)];
    }
  }
  throw Error('Seat state is wrong. No seat selected: ' + seats.toString());
}

export function findArchiveConfiguration(
    activeSound: string, sounds: Sound[], seats: boolean[],
    configJson: any): any|Error {
  const mode = sounds.find((sound) => sound.name === activeSound)!.activeMode;
  const selectedSeat = findSelectedSeat(seats, configJson);
  let name: string = ''
  let parameters: any = []
  configJson.dar_configs.forEach((config: any) => {
    if (selectedSeat.name === config.id_seat && mode === config.id_mode) {
      name = config.name;
      if (config.parameters) {
        parameters = config.parameters;
      }
    }
  });

  if (name === '') {
    throw Error(`Configuration not found for:
          id_seat: ${selectedSeat.name}
          id_mode: ${mode}`)
  }
  return {name: name, parameters: parameters};
}

// Checks if:
// - Validate the dar file is present in the API data
// - All JSON configurations link to DAR archive.
// - All DAR archives link to JSON configurations.
// - All combinations of seat/mode are map to a JSON configuration.
export async function validateConfigJson(
    json_data: any, setApiStatus: CallableFunction): Promise<void|string> {
  const apiData = await ApiGetAllArchives(json_data, setApiStatus);
  if (apiData === null) {
    throw Error(`API is down`)
  }

  // Log in the console the API and JSON configuration.
  console.log('API data: \n', apiData);

  // Validate the dar file is present in the API data (for debugging)
  if (!(json_data.dar_file in apiData)) {
    throw Error(`Dar file in json configuration (${
        json_data.dar_file}) is not present in the API data`)
  }

  // All JSON configurations link to DAR archive.
  // Loop through each config in the JSON file
  json_data.dar_configs.forEach((jsonConfig: any) => {
    // Check if JSON config matches any of the API configs
    if (!apiData[json_data.dar_file].some(
            (apiConfig: string) => jsonConfig.name === apiConfig)) {
      // If the dar_config is not found, log an error
      console.error(`Configuration in JSON file "${
          jsonConfig.name}" not found in the dar file.
          Check ${json_data.api_url}/config.json`)
    }
  });

  // All DAR archives link to JSON configurations.
  // Loop through each API config
  apiData[json_data.dar_file].forEach((apiConfig: string) => {
    // Check if API config matches any of the JSON configs

    if (!json_data.dar_configs.some(
            (jsonConfig: any) => jsonConfig.name === apiConfig)) {
      // If the dar_config is not found, log an error
      console.error(
          `Configuration in API "${apiConfig}" not mapped in the JSON file.
          Check ${json_data.api_url}/config.json`)
    }
  });

  // All combinations of seat/mode are map to a JSON configuration.
  json_data.tabs.forEach((tab: any) => {
    tab.modes.forEach((mode: any) => {
      json_data.seats.forEach((seat: Seat) => {
        let configuration = '';
        json_data.dar_configs.forEach((config: any) => {
          if (seat.name === config.id_seat && mode.name === config.id_mode) {
            configuration = config.name;
          }
        });
        if (configuration === '') {
          console.error(`Missing combination of seat/mode in the JSON file for:
                id_seat: ${seat.name}
                id_mode: ${mode.name}
                Check ${json_data.api_url}/config.json`)
        }
      });
    });
  })
}

// This is used when the user starts the application and the API is connected
export function findConfiguration(
    json_data: any, archive: any, initialState: any) {
  let new_seats: boolean[] = [];
  let parameters: [] = [];
  for (const config of json_data.dar_configs) {
    if (config.name === archive.configuration) {
      if (config.parameters?.length > 0) {
        parameters = config.parameters
      }
      for (const tab of json_data.tabs) {
        for (const mode of tab.modes) {
          if (mode.name === config.id_mode) {
            for (const seat of json_data.seats) {
              if (seat.name === config.id_seat) {
                new_seats.push(true);
              } else {
                new_seats.push(false);
              }
            }
            if (new_seats.every(value => value === false)) {
              throw Error(
                  'No configuration matching seat has been found for archive: ' +
                  archive.configuration)
            }
            return {
              seats: new_seats, sound: tab.name, mode: mode,
                  parameters: parameters
            }
          }
        }
      }
    }
  }
  if (archive.configuration !== '') {
    throw Error('Configuration not found for archive: ' + archive.configuration)
  }
}

export function dbToLinear(dB: number) {
  return Math.pow(10, dB / 20);
}

export function linearToDb(linearValue: number) {
  return 20 * Math.log10(linearValue);
}

export function dbTodbClamped(
    dB: number, minDb: number, maxDb: number): number {
  return Math.round(Math.max(minDb, Math.min(maxDb, dB)));
}

export function saveLogsAndErrorsToFile(
    logs: string[], errors: string[], fileName: string) {
  const content = `
App version: ${process.env.REACT_APP_VERSION};

Captured Logs:
${logs.join('\n')}

Captured Errors:
${errors.join('\n')}
`;

  const blob = new Blob([content], {type: 'text/plain'});
  const url = URL.createObjectURL(blob);

  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;

  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);

  URL.revokeObjectURL(url);
}

export function getMode(sounds: Sound[], activeSound: string) {
  const actualSound: Sound|undefined =
      sounds.find(sound => sound.name === activeSound);
  const actualMode: SoundMode|undefined =
      actualSound?.modes.find(mode => mode.name === actualSound.activeMode)
  return actualMode;
}