import { useAutomotiveSoundStore } from 'src/store/store';
import { ApiSetActiveArchive } from 'src/utils/api';

const Navbar = () => {
    const {
        json_data,
        sounds,
        seats,
        activeSound,
        setApiStatus,
        changeActiveSound,
        setProxyParameters,
    } = useAutomotiveSoundStore();

    const selectActiveSound = async (sound: string) => {
        changeActiveSound(sound);
        await ApiSetActiveArchive(sound, sounds, seats, json_data,setProxyParameters, setApiStatus);
    };

    return (
        <div className="c-navbar">
            {sounds && sounds.length !== 1 && // skip if there is only 1 tab
                sounds.map((sound) => (
                    <div className="c-navbar__nav-item" key={sound.name}>
                        <button key={sound.name} className={`c-navbar__nav-item__btn
                            ${activeSound === sound.name && 'sound--active'}`}
                            onClick={async () => await selectActiveSound(sound.name)}>
                            {sound.name}
                        </button>
                    </div>
                ))}
        </div>
    );
};

export default Navbar;
