import { useEffect, useCallback, useRef, useState } from 'react';
import { ApiFetchConfigJson, ApiGetActiveArchive, ApiGetCurrentVolume, ApiUpdateProxyParameters, ApiGetParameter} from 'src/utils/api';
import { useAutomotiveSoundStore, initialState } from "src/store/store";
import { validateConfigJson, findConfiguration, findArchiveConfiguration } from 'src/utils/helpers';

export default function ApiComponent() {
    const {
        changeActiveSound,
        changeSoundMode,
        setConfigJson,
        setApiStatus,
        updateSeats,
        setDbAmount,
        setProxyParameters,
        apiStatus,
    } = useAutomotiveSoundStore();

    const hasFetchedDataRef = useRef(false); // Used to fetch the JSON data only once

    const fetchData = async (
        json_data: any,
        updateSeats: CallableFunction,
        changeActiveSound: CallableFunction,
        changeSoundMode: CallableFunction,
        setApiStatus: CallableFunction,
        setDbAmount: CallableFunction,
        setProxyParameters: CallableFunction,
        apiStatus: string
    ) => {
        if (apiStatus === "Connecting") {
            return;
        }
        setApiStatus("Connecting");

        ApiGetActiveArchive(json_data, setApiStatus).then(archive => {
            let configuration = findConfiguration(json_data, archive, initialState);
            if (configuration && apiStatus !== "Connecting") {
                updateSeats(configuration.seats);
                changeActiveSound(configuration.sound);
                changeSoundMode(configuration.mode.name);
                if (configuration.parameters) {
                    ApiUpdateProxyParameters(
                        setProxyParameters, json_data, setApiStatus, configuration.parameters);
                }
            }
        });

        ApiGetCurrentVolume(json_data, setApiStatus).then(volume => {
            setDbAmount(volume, json_data.gain.min, json_data.gain.max);
        })

    };

    // Fetch JSON data from the API and set the state
    const updateJson = useCallback(async (configJsonFile:string) => {
        // Report the App version to the console log
        console.log(`App version: ${process.env.REACT_APP_VERSION}`);

        const json_data = await ApiFetchConfigJson(configJsonFile);
        console.log('Config file:', configJsonFile);

        setConfigJson(json_data);

        // Report the complete json data to the console log
        console.log('JSON data:', json_data);

        // Fetch data from the API
        await fetchData(json_data, updateSeats, changeActiveSound, changeSoundMode, setApiStatus, setDbAmount, setProxyParameters, apiStatus);

        // Set the config json and validate the errors
        await validateConfigJson(json_data, setApiStatus);

        if (json_data.update_continuously) {
            const intervalId = setInterval(fetchData,
                json_data.update_continuously_time_ms,
                json_data, updateSeats,
                changeActiveSound,
                changeSoundMode,
                setApiStatus,
                setDbAmount,
                setProxyParameters,
                apiStatus
            );
            return () => {
                clearInterval(intervalId);  // Clear the interval when the component unmounts
            };
        }
    }, [setConfigJson, setApiStatus, updateSeats, changeActiveSound, changeSoundMode, setDbAmount, setProxyParameters, apiStatus]);

    // Trigger the initial JSON data fetch
      useEffect(() => {
        if (!hasFetchedDataRef.current) {
            const urlParams = new URLSearchParams(window.location.search);
            if (urlParams.get('demo') !== null) {
                updateJson("demos/" + urlParams.get('demo')! + "/config.json");
            }
            else {
                updateJson("config.json");
            }
            hasFetchedDataRef.current = true;
        }
    }, [updateJson]);

    return null; // This component doesn't render anything visible
}
