import {ProxyParameter, Sound} from '../store/store';
import {dbToLinear, findArchiveConfiguration, linearToDb} from '../utils/helpers';

// Function to make a GET request to the API
export async function ApiGetRequest(
    api_url: string, endpoint: string,
    setApiStatus: CallableFunction): Promise<any> {
  try {
    const response = await fetch(api_url + endpoint);
    if (!response.ok) {
      setApiStatus('Failed');
      throw new Error('Network response was not ok');
    }
    setApiStatus('Connected');
    const data = await response.json();
    return data;
  } catch (error) {
    setApiStatus('Failed');
    throw Error('API is down. Error fetching data:' + error)
  }
}

// Function to make a PUT request to the API
export async function ApiPutRequest(
    api_url: string, endpoint: string, data: any,
    setApiStatus: CallableFunction): Promise<any> {
  try {
    setApiStatus('Connecting');
    let response = await fetch(api_url + endpoint, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data),
    });
    if (!response.ok) {
      setApiStatus('Failed');
      throw new Error('Network response was not ok');
    }
    let responseText = await response.text();

    let output
    // If the API does not return any data, make a GET request
    if (responseText === '') {
      output = await ApiGetRequest(api_url, endpoint, setApiStatus);
    }
    else {
      output = JSON.parse(responseText);
    }

    setApiStatus('Connected');
    return output;
  } catch (error) {
    setApiStatus('Failed');
    throw new Error('API is down. Error sending data:' + error);
  }
}

// Function to get all archives and configurations
export async function ApiGetAllArchives(
    json_data: any, setApiStatus: CallableFunction): Promise<any> {
  const endpoint = json_data.api?.archives || 'archives';
  return await ApiGetRequest(json_data.api_url, endpoint, setApiStatus);
}

// Function to get or set the current archive and configuration
export async function ApiGetActiveArchive(
    json_data: any, setApiStatus: CallableFunction): Promise<any> {
  const endpoint = json_data.api?.archive || 'activeArchive';
  return await ApiGetRequest(json_data.api_url, endpoint, setApiStatus);
}

export async function ApiSetActiveArchive(
    activeSound: string, sounds: Sound[], seats: boolean[], json_data: any,
    setProxyParameters: CallableFunction,
    setApiStatus: CallableFunction): Promise<void|string> {
  const endpoint = json_data.api?.archive || 'activeArchive';
  let dar_file = json_data.dar_file
  let configuration =
      findArchiveConfiguration(activeSound, sounds, seats, json_data);
  const expectedArchive = {
    archive: dar_file,
    configuration: configuration.name,
  };

  try {
    // Send the configuration to API
    const activeArchive = await ApiPutRequest(
        json_data.api_url, endpoint, expectedArchive, setApiStatus);

    // Verify the configuration has been set correctly
    const activeArchiveString = JSON.stringify(activeArchive);
    const expectedArchiveString = JSON.stringify(expectedArchive);

    if (activeArchiveString !== expectedArchiveString) {
      throw Error(`Configuration error:
          expectedArchive: ${expectedArchiveString}
          activeArchiveString: ${activeArchiveString}`)
    }
    if (configuration.parameters) {
      await ApiUpdateProxyParameters(
          setProxyParameters, json_data, setApiStatus,
          configuration.parameters);
    } else {
      setProxyParameters([]);
    }
  } catch (error) {
    throw Error(`Failed in setActiveArchive:\n
      Dar filename: ${dar_file}
      Dar configuration: ${configuration.name}`)
  }
}

export async function ApiUpdateProxyParameters(
    setProxyParameters: CallableFunction, json_data: any,
    setApiStatus: CallableFunction,
    json_data_parameters_for_config: []): Promise<void> {
  let parameters: any[] = [];
  await Promise.all(
      json_data_parameters_for_config.map(async (parameter_id: number) => {
        let parameters_data = await ApiGetParameters(json_data, setApiStatus);
        Object.keys(parameters_data).forEach((key: string) => {
          const parameter_data = parameters_data[key];
          if (parameter_data.id === parameter_id) {
            if (parameter_data.stepSize === 0) {
              // It is integer, default to 1
              parameter_data.stepSize = 1;
            }
            parameter_data.value = parameter_data.plainValue;
            parameters.push(parameter_data);
          }
        });
      }));
  setProxyParameters(parameters);
}

// Function to get or set the current volume
export async function ApiGetCurrentVolume(
    json_data: any, setApiStatus: CallableFunction): Promise<number> {
  const endpoint = json_data.api?.volume || 'volume';
  const request =
      await ApiGetRequest(json_data.api_url, endpoint, setApiStatus);
  return linearToDb(request.volume);
}

export async function ApiSetCurrentVolume(
    masterGain: number, json_data: any,
    setApiStatus: CallableFunction): Promise<any> {
  const endpoint = json_data.api?.volume || 'volume';
  const linear_gain = dbToLinear(masterGain);
  const volumeData = {
    volume: linear_gain,
  };
  return await ApiPutRequest(
      json_data.api_url, endpoint, volumeData, setApiStatus);
}

export async function ApiSetParameter(
    id: number, value: number, json_data: any,
    setApiStatus: CallableFunction): Promise<any> {
  let endpoint = json_data.api?.parameter || 'proxyParameterPlainValue/';
  endpoint += id;
  const data = {
    plainValue: value,
  };
  return await ApiPutRequest(json_data.api_url, endpoint, data, setApiStatus);
}

export async function ApiGetParameter(
    id: number, json_data: any, setApiStatus: CallableFunction): Promise<any> {
  let endpoint = json_data.api?.parameter || 'proxyParameterPlainValue/';
  endpoint += id;
  return await ApiGetRequest(json_data.api_url, endpoint, setApiStatus);
}

export async function ApiGetParameters(
    json_data: any, setApiStatus: CallableFunction): Promise<any> {
  const endpoint = json_data.api?.parameters || 'proxyParameters';
  const request =
      await ApiGetRequest(json_data.api_url, endpoint, setApiStatus);
  return request;
}

export async function ApiFetchConfigJson(configJsonFile: string): Promise<any> {
  let data;
  try {
    const response = await fetch(configJsonFile);
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    data = await response.json();
  } catch (error) {
    throw Error('API is down. Error fetching data:' + error);
  }
  return data;
}
