import SelectSeats from "./Select.seats";
import Slider from '@mui/material/Slider';
import { useAutomotiveSoundStore } from "src/store/store";
import { findSelectedSeat, getMode } from "src/utils/helpers"
import { ApiSetParameter } from "src/utils/api"
import Header from "./Header";

const Landing = () => {
    const { json_data, sounds, activeSound, seats, parameters, setProxyParameterValue,  setApiStatus } = useAutomotiveSoundStore();

    function generateSeatElements(placeholdersIndexes: number[]) {
        return placeholdersIndexes.map(index => {
            return <div key={index} style={{
                left: json_data.seat_placeholders_positions[index][0] + "%",
                top: json_data.seat_placeholders_positions[index][1] + "%",
                width: (json_data.style?.seat_placeholder?.width || "41px"),
                height: (json_data.style?.seat_placeholder?.height || "27px"),
                border: (json_data.style?.seat_placeholder?.border || "2px solid var(--base_outline_2, #536CB2)"),
                backgroundColor: (json_data.style?.seat_placeholder?.background || "rgba(51, 64, 85, .8)"),
                borderRadius: (json_data.style?.seat_placeholder?.border_radius || "8px")
           }} className="seat-placeholder"></div>;
        });
    }

    function resolveSeatPositions(json_data: any, seats: boolean[]) {
        const seat = findSelectedSeat(seats, json_data);
        if (seat === null) {
            throw new Error("Seat selection is invalid. Seats:" + seats.toString());
        } else {
            return generateSeatElements(seat.placeholders);
        }
    }
    const updateProxyParameter = async (parameter: any, value: number) => {
        setProxyParameterValue(parameter.id, value);
        await ApiSetParameter(parameter.id, value, json_data, setApiStatus)
    };

    return (
        <>
            <Header />
            <div className="c-landing__wrapper">
                <div className="c-landing">
                    <SelectSeats />
                    <div className="c-landing__car" style={{ marginLeft: 'auto', display: 'flex', justifyContent: 'flex-end' }}>
                        <img
                            className="c-landing__car-sound"
                            src={getMode(sounds, activeSound)?.image}
                            alt=""
                        />
                        {parameters && parameters.length !== 0 && (
                            <div className="c-landing__car-slider">
                                {parameters.map((parameter: any) => (
                                    <div key={parameter['id']} className="c-landing__car-slider-item">
                                        <h3>{parameter['name']}</h3>
                                            <Slider
                                                aria-label={parameter['name']}
                                                orientation="vertical"
                                                defaultValue={parameter['plainValue']}
                                                step={parameter['stepSize']}
                                                min={parameter['min']}
                                                max={parameter['max']}
                                                marks={[
                                                    {
                                                        value: parameter['min'],
                                                        label: parameter['min'],
                                                    },
                                                    {
                                                        value: parameter['max'],
                                                        label: parameter['max'],
                                                    },
                                            ]}
                                                onChange={async (_e, value) => await updateProxyParameter(parameter, value as number)}
                                                valueLabelDisplay="on"
                                                value={parameter.value}
                                            />
                                    </div>
                                ))}
                            </div>
                        )}
                        <div className={"c-landing__car-image"}>
                            <img src={json_data.images.bird_view} alt="" style={{ filter: json_data.style?.images?.bird_view_filter || 'grayscale(100%)' }}/>
                        </div>
                        <div className={"c-landing__car-image placeholder"}>
                            <img src={json_data.images.bird_view} alt="" style={{ opacity: 0 }} />
                            {json_data.show_seats && (typeof json_data.show_seats == "boolean" ||
                                json_data.show_seats.includes(getMode(sounds, activeSound)?.name))
                                && (<div className="c-landing__car-image__seats">
                                    {resolveSeatPositions(json_data, seats)}
                                </div>
                                )}
                        </div>

                    </div>

                </div>

            </div>
        </>
    );
};

export default Landing;
