import { useAutomotiveSoundStore } from "src/store/store";
import { saveLogsAndErrorsToFile } from "src/utils/helpers";
import errorIcon from "src/assets/svg/icons8-error.png";
import "./notification.scss";

const Notification = () => {
    const { errorMessage, setErrorMessage, logs, errors, json_data } = useAutomotiveSoundStore();

    if (!errorMessage) return null;

    // Replace newline characters with HTML line breaks
    let formattedErrorMessage = errorMessage.replace(/\n/g, "<br />");
    formattedErrorMessage += "<br/><br/>Kindly reach out to support before proceeding."
    return (
        <div>
            <div className="overlay"></div>
            <div className="c-notification__wrapper fade-in">
                <div className="c-notification">
                    <img src={errorIcon} alt="Error icon" />
                    {/* Render the formattedErrorMessage using dangerouslySetInnerHTML */}
                    <div>
                        <p dangerouslySetInnerHTML={{ __html: formattedErrorMessage }}></p>
                            <div>
                                <button className="c-notification__download" onClick={() => saveLogsAndErrorsToFile(logs, errors, json_data.log_file)}>
                                    Download log file
                                </button>
                                <a className="c-notification__download" href="config.json" download>
                                    Download config.json
                                </a>
                                <br /> {/* Add a line break for spacing */}
                            </div>
                    </div>
                    <button onClick={() => setErrorMessage("")} className="remove-error-btn">
                        X
                    </button>
                </div>
            </div>
        </div >

    );
};
export default Notification;
