import "./quantity.input.scss";
import { useAutomotiveSoundStore } from "src/store/store";
import { ApiSetCurrentVolume } from 'src/utils/api';

const QuantityInput = () => {

    const { json_data, masterGain, setDbAmount, setApiStatus } = useAutomotiveSoundStore();

    const selectVolume = (masterGain: number) => {
        setDbAmount(masterGain, json_data.gain.min, json_data.gain.max);
        ApiSetCurrentVolume(masterGain, json_data, setApiStatus);
    };

    return (
        <div className="c-quantity-input">
            <button onClick={() => selectVolume(masterGain - 1)}>-</button>
            <div className="c-quantity-input__field-container">
                <input
                    type="number"
                    name=""
                    id=""
                    value={masterGain}
                    onChange={(e: any) => selectVolume(e.target.value)}
                    className="c-quantity-input__field"
                    readOnly
                />
                dB
            </div>
            <button onClick={() => selectVolume(masterGain + 1)}>+</button>
        </div>
    );
};
export default QuantityInput;
