import React, { useEffect, useRef } from 'react';
import modeIcon from 'src/assets/svg/mode-icon.png';
import {
    useAutomotiveSoundStore,
    selectSound,
} from 'src/store/store';
import { ApiSetActiveArchive } from 'src/utils/api';

const Footer = () => {
    const {
        json_data,
        sounds,
        apiStatus,
        seats,
        activeSound,
        setProxyParameters,
        changeSoundMode,
        setApiStatus,
    } = useAutomotiveSoundStore();

    const selectSoundMode = async (mode: string) => {
        changeSoundMode(mode);
        let tmpSounds = selectSound(sounds, activeSound, mode);
        await ApiSetActiveArchive(activeSound, tmpSounds, seats, json_data, setProxyParameters,  setApiStatus);
    };

    return (
        <div className="c-footer">
            <div className="c-footer__nav">
                <div className="c-footer__nav-title">Select mode</div>
                <div className="c-footer__nav-mode">
                    <img src={modeIcon} alt="" />
                    <p>
                        {
                            sounds.find((sound) => sound.name === activeSound)
                                ?.activeMode
                        }
                    </p>
                </div>
                <div className="c-footer__nav-apistatus">
                    <p>
                        API status:{' '}
                        <span className={`c-footer__nav-apistatus-${apiStatus !== "Failed" ? 'ok' : 'failed'}`}>
                            {apiStatus !== "Failed" ? 'Connected' : 'Failed'}
                        </span>
                    </p>
                </div>
            </div>
            <div className="c-footer__main">
                <div className="c-footer__main__mode">
                    {sounds
                        .find((sound) => sound.name === activeSound)!
                        .modes.map((mode) => (
                            <div
                                onClick={async () => await selectSoundMode(mode.name)}
                                className={`c-footer__main__mode-item ${mode.name ===
                                    sounds.find(
                                        (sound) => sound.name === activeSound
                                    )?.activeMode
                                    ? "mode--active"
                                    : ""
                                    }`}
                                key={mode.name}
                            >
                                <h3>{mode.name}</h3>
                                <p key={mode.name}>{mode.description}</p>
                            </div>
                        ))}
                </div>
            </div>
        </div>
    );
};

export default Footer;
