import { useState } from 'react';
import { getMode, findConfiguration } from "src/utils/helpers"
import { Seat, useAutomotiveSoundStore } from "src/store/store";
import { ApiSetActiveArchive } from 'src/utils/api';

const SelectSeats = () => {
    const { json_data, seats: initialSeats, seats, updateSeats, activeSound, sounds, parameters, setProxyParameters, setApiStatus } = useAutomotiveSoundStore();

    const [tmpSeats, setSeats] = useState(initialSeats);

    const selectSeat = async (seat: number) => {
        const updatedSeats = Object.keys(tmpSeats).reduce((updated: any, x) => {
            updated[x] = Number(x) === seat;
            return updated;
        }, {});
        setSeats(updatedSeats);
        updateSeats(updatedSeats);

        // Call the API function with the latest state
        await ApiSetActiveArchive(activeSound, sounds, updatedSeats, json_data, setProxyParameters, setApiStatus);
    };

    const getSeatClass = (seat: number) => {
        return seats[seat] ? 'seat--selected' : ''
    };

    return (
        <div className="c-landing__select-seats">
            {json_data.show_seats && (typeof json_data.show_seats == "boolean" ||
                json_data.show_seats.includes(getMode(sounds, activeSound)?.name)) && (
                    <>
                        <h4 className="c-landing__select-seats-title">
                            {json_data.seats_title}
                        </h4>
                        <div className="c-landing__select-seats-buttons">
                            {json_data.seats.map((seat: Seat, index: number) => (
                                <button
                                    key={index}
                                    onClick={ async () => await selectSeat(index)}
                                    className={getSeatClass(index)}>
                                    {seat.name}
                                </button>
                            ))}
                        </div>
                    </>
                )}
        </div>
    );
};
export default SelectSeats;
