import {produce} from 'immer';
import {create} from 'zustand';
import {devtools} from 'zustand/middleware';

import {dbTodbClamped} from '../utils/helpers';

export type SoundMode = {
  name: string; description: string, image: string; subtitle: string;
};

export type Sound = {
  name: string; activeMode: string; modes: SoundMode[];
};

export type Seat = {
  name: string; placeholders: number[];
};

export type ProxyParameter = {
  value: number; id: number;
};

export interface AutomativeSoundState extends AutomativeSoundProps {
  updateSeats: (seats: boolean[]) => void;
  changeSoundMode: (mode: string) => void;
  changeActiveSound: (sound: string) => void;
  setDbAmount: (n: number, min_gain: number, max_gain: number) => void;
  setProxyParameters: (parameters: ProxyParameter[]) => void;
  setProxyParameterValue: (id: number, value: number) => void;
  setErrorMessage: (t: string) => void;
  setConfigJson: (data: any) => void;
  setApiStatus: (apiStatus: string) => void;
  captureLogsAndErrors: () => void;
}

interface AutomativeSoundProps {
  sounds: Sound[];
  activeSound: string;
  masterGain: number;
  seats: boolean[];
  parameters: ProxyParameter[];
  errorMessage: string;
  json_data: any, apiStatus: string, logs: string[], errors: string[],
}

export const initialState: AutomativeSoundProps = {
  activeSound: 'Stereo',
  errorMessage: '',
  json_data: {},
  sounds: [],
  masterGain: 0,
  seats: [],
  parameters: [],
  apiStatus: 'Connected',
  logs: [],
  errors: []
};

export function selectSound(
    sounds: Sound[], activeSound: string, mode: string) {
  let tmpSounds = sounds.map(
      (sound) =>
          sound.name === activeSound ? {...sound, activeMode: mode} : sound);
  return tmpSounds;
}

export const useAutomotiveSoundStore = create<AutomativeSoundState>()(devtools(
    (set) => {return ({
      ...initialState,
      updateSeats: (seats: boolean[]) => {
          set(produce((state: AutomativeSoundState) => {
                state.seats = seats;
              }),
              false, `Update seats to: ${seats}`)},
      changeActiveSound: (sound: string) =>
          set(produce((state: AutomativeSoundState) => {
                state.activeSound = sound;
              }),
              false, `Set active sound to: ${sound}`),
      changeSoundMode: (mode: string) => set(
          produce((state: AutomativeSoundState) => {
            state.sounds = selectSound(state.sounds, state.activeSound, mode);
          }),
          false, `Change mode to: ${mode}`),
      setDbAmount: (dB: number, min_gain: number, max_gain: number) => {
          set(produce((state: AutomativeSoundState) => {
                dB = dbTodbClamped(dB, min_gain, max_gain);
                state.masterGain = dB;
              }),
              false, `Set dB amount to: ${dB} db`)},
      setProxyParameters: (parameters: ProxyParameter[]) =>
          set(produce((state: AutomativeSoundState) => {
                state.parameters = parameters;
              }),
              false, `Set proxy parameter`),
      setProxyParameterValue: (id: number, value: number) =>
          set(produce((state: AutomativeSoundState) => {
                for (const parameter of state.parameters) {
                  if (parameter.id === id) {
                    parameter.value = value;
                  }
                }
              }),
              false, `Update proxy parameter: ${id} to ${value}`),
      setErrorMessage: (e: string) =>
          set(produce((state: AutomativeSoundState) => {
                state.errorMessage = e;
              }),
              false, `Set error message: ${e}`),
      setConfigJson: (data: any) => set(
          produce((state: AutomativeSoundState) => {
            state.json_data = data;

            // Update tabs/modes with json data
            for (const indx in data.tabs) {
              state.sounds.push({
                name: data.tabs[indx].name,
                activeMode: data.tabs[indx].modes[0].name,
                modes: data.tabs[indx].modes,
              })
            }

            // Update seats with json data
            state.seats = Array.from({length: data.seats.length}, () => false);
            state.seats[0] = true;  // Set a default
          }),
          false, `Set error message:`),
      setApiStatus: (apiStatus: string) =>
          set(produce((state: AutomativeSoundState) => {
                state.apiStatus = apiStatus;
              }),
              false, `Set error message:`),

      // Call the helper function to capture logs and errors
      captureLogsAndErrors: () => {
        const originalConsoleLog = console.log;
        const originalConsoleError = console.error;

        console.log = function(...args: any[]) {
          const log = args.join(' ');
          set((state) => ({...state, logs: [...state.logs, log]}));
          originalConsoleLog(...args);
        };

        console.error = function(...args: any[]) {
          const error = args.join(' ');
          set((state) => ({...state, errors: [...state.errors, error]}));
          originalConsoleError(...args);
        };
      }
    })}));
